WITH flattened AS (SELECT id, service, host, level, status_code, key, attr_value FROM app_logs LATERAL VIEW EXPLODE(context) x AS key, attr_value) SELECT id, host, status_code, key, ROUND(status_code / SUM(status_code) OVER (PARTITION BY host), 4) status_code_share, CUME_DIST() OVER (ORDER BY status_code DESC) status_code_cume_dist, FIRST_VALUE(key) IGNORE NULLS OVER (PARTITION BY host, service ORDER BY status_code, id, key ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) first_known_key, ROUND(status_code / SUM(status_code) OVER (PARTITION BY key), 4) status_code_share_2, FIRST_VALUE(key) IGNORE NULLS OVER (PARTITION BY key, level ORDER BY status_code, id, key ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) first_known_key_2 FROM flattened;
